1|/**
2| * Effect registry.
3| *
4| * The captured markup is static: every behaviour the original page's JavaScript
5| * provided has to be re-implemented here. Each effect is an independent
6| * `EffectInit` that finds its own targets by selector and returns a teardown
7| * function, so effects can be enabled per-site without touching this file.
8| *
9| * Two rules every effect must follow:
10| *  1. No-op silently when its targets are absent (a site without a carousel
11| *     must not throw).
12| *  2. Be idempotent — React strict mode mounts effects twice in development.
13| */
14|
15|export type Teardown = () => void;
16|export type EffectInit = (root?: ParentNode) => Teardown | void;
17|
18|export interface RegisteredEffect {
19|  name: string;
20|  init: EffectInit;
21|}
22|
23|/** True when the visitor asked for reduced motion; several effects honour it. */
24|export function prefersReducedMotion(): boolean {
25|  if (typeof window === 'undefined' || !window.matchMedia) return false;
26|  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
27|}
28|
29|/** rAF-throttled wrapper for scroll/resize handlers. */
30|export function rafThrottle<A extends unknown[]>(fn: (...args: A) => void) {
31|  let queued = false;
32|  let lastArgs: A;
33|  return (...args: A) => {
34|    lastArgs = args;
35|    if (queued) return;
36|    queued = true;
37|    requestAnimationFrame(() => {
38|      queued = false;
39|      fn(...lastArgs);
40|    });
41|  };
42|}
43|
44|export function $all<T extends Element = HTMLElement>(
45|  selector: string,
46|  root: ParentNode = document,
47|): T[] {
48|  return Array.from(root.querySelectorAll<T>(selector));
49|}
50|
51|/**
52| * Runs every effect, collecting teardowns. A throwing effect is logged and
53| * skipped rather than taking the whole page down with it.
54| */
55|export function initEffects(effects: RegisteredEffect[], root: ParentNode = document): Teardown {
56|  const teardowns: Teardown[] = [];
57|  for (const { name, init } of effects) {
58|    try {
59|      const t = init(root);
60|      if (typeof t === 'function') teardowns.push(t);
61|    } catch (err) {
62|      console.error(`[replica] effect "${name}" failed to initialise:`, err);
63|    }
64|  }
65|  return () => {
66|    for (const t of teardowns) {
67|      try {
68|        t();
69|      } catch {
70|        /* teardown must never throw during unmount */
71|      }
72|    }
73|  };
74|}
75|

