1|/**
2| * Adapters for library-backed effects.
3| *
4| * The template ships ZERO animation/carousel dependencies, because which ones
5| * a given page needs is only known after `npm run extras` reports what the
6| * original loaded. Rather than guessing, each adapter takes a `load` callback
7| * that dynamically imports the library, so:
8| *
9| *   - the template type-checks and builds with nothing extra installed;
10| *   - installing the exact detected version wires the effect up in one line;
11| *   - a missing library degrades to a logged warning, not a crashed page.
12| *
13| * Usage in ClientRuntime.tsx (only after `npm i swiper`):
14| *
15| *   createCarousel({ load: () => import('swiper/bundle') })
16| */
17|import { $all, type Teardown } from './runtime';
18|
19|/* eslint-disable @typescript-eslint/no-explicit-any */
20|type AnyModule = any;
21|
22|export interface CarouselOptions {
23|  /** Dynamic import of the carousel library, e.g. () => import('swiper/bundle'). */
24|  load: () => Promise<AnyModule>;
25|  rootSelector?: string;
26|  /** Passed straight through to the library constructor. */
27|  params?: Record<string, unknown>;
28|  /** Pick the constructor out of the module (default: Swiper-shaped). */
29|  pick?: (mod: AnyModule) => AnyModule;
30|}
31|
32|/**
33| * Initialises a Swiper-compatible carousel on every matching root.
34| * Mirrors the original page's own `new Swiper(el, params)` call.
35| */
36|export function createCarousel(options: CarouselOptions) {
37|  const {
38|    load,
39|    rootSelector = '.swiper, [class*="swiper-container"]',
40|    params = { slidesPerView: 'auto', loop: true, speed: 600 },
41|    pick = (mod) => mod.Swiper ?? mod.default ?? mod,
42|  } = options;
43|
44|  return function initCarousel(root: ParentNode = document): Teardown | void {
45|    const roots = $all(rootSelector, root);
46|    if (!roots.length) return;
47|
48|    let disposed = false;
49|    const instances: AnyModule[] = [];
50|
51|    void load()
52|      .then((mod) => {
53|        if (disposed) return;
54|        const Ctor = pick(mod);
55|        if (typeof Ctor !== 'function') {
56|          console.warn('[replica] carousel module had no usable constructor');
57|          return;
58|        }
59|        for (const el of roots) {
60|          try {
61|            instances.push(new Ctor(el, params));
62|          } catch (err) {
63|            console.warn('[replica] carousel failed to initialise on', el, err);
64|          }
65|        }
66|      })
67|      .catch((err) => {
68|        console.warn(
69|          '[replica] carousel library not installed — slides will render statically.',
70|          err,
71|        );
72|      });
73|
74|    return () => {
75|      disposed = true;
76|      for (const inst of instances) {
77|        try {
78|          inst.destroy?.(true, true);
79|        } catch {
80|          /* library teardown is best-effort */
81|        }
82|      }
83|    };
84|  };
85|}
