1|/**
2| * Form handling.
3| *
4| * A replica must never POST to the original site's endpoint: that would send
5| * real submissions to somebody else's CRM. Instead, forms are intercepted and
6| * the site's own success/error state is toggled locally, so the interaction
7| * looks and feels identical without any network side effect.
8| */
9|import { $all, type Teardown } from './runtime';
10|
11|export interface FormOptions {
12|  formSelector?: string;
13|  /** Sibling/parent elements the original markup uses for the result states. */
14|  successSelector?: string;
15|  errorSelector?: string;
16|  /** Simulated round-trip, so the pending state is actually visible. */
17|  latencyMs?: number;
18|  /** Called with the collected fields instead of submitting anywhere. */
19|  onSubmit?: (data: Record<string, string>, form: HTMLFormElement) => void;
20|}
21|
22|export function createForms(options: FormOptions = {}) {
23|  const {
24|    formSelector = 'form',
25|    successSelector = '.w-form-done, [data-form-success], .form-success',
26|    errorSelector = '.w-form-fail, [data-form-error], .form-error',
27|    latencyMs = 600,
28|    onSubmit,
29|  } = options;
30|
31|  return function initForms(root: ParentNode = document): Teardown | void {
32|    const forms = $all<HTMLFormElement>(formSelector, root);
33|    if (!forms.length) return;
34|
35|    const cleanups: Array<() => void> = [];
36|
37|    for (const form of forms) {
38|      const parent = form.parentElement;
39|      const success =
40|        parent?.querySelector<HTMLElement>(successSelector) ??
41|        form.querySelector<HTMLElement>(successSelector);
42|      const error =
43|        parent?.querySelector<HTMLElement>(errorSelector) ??
