--- a/coframecom-3/app/lib/coframeHeroAnim.ts
+++ b/coframecom-3/app/lib/coframeHeroAnim.ts
@@ -0,0 +1,191 @@
+/**
+ * Hero entrance fades — ported from Webflow IX2 action list "a-3"
+ * ("Hero Animations"), which `webflow.js` used to run and which the codegen
+ * sanitizer therefore strips.
+ *
+ * Transcribed verbatim from the IX2 payload in
+ * `scrape/raw/js/webflow.schunk.571c3827ae3ad973.a275af80.js`:
+ *
+ *   events["e-3"] = { eventTypeId: "PAGE_START", actionListId: "a-3",
+ *                     config.loop: false }
+ *
+ *   actionLists["a-3"] = { useFirstGroupAsInitialState: true, groups:
+ *     G1 (initial state):
+ *       STYLE_OPACITY 674d6aa7-...-b376  value 0  delay    0  duration 500
+ *       STYLE_OPACITY 674d6aa7-...-b395  value 0  delay    0  duration 500
+ *       STYLE_OPACITY 355463fa-...-5720  value 0  delay    0  duration   0
+ *     G2:
+ *       STYLE_OPACITY 355463fa-...-5720  value 1  delay  500  duration 300  easeInOut
+ *     G3:
+ *       STYLE_OPACITY 674d6aa7-...-b376  value 1  delay 1300  duration 300  easeInOut
+ *       STYLE_OPACITY 674d6aa7-...-b395  value 1  delay 1700  duration 300  easeInOut
+ *   }
+ *
+ * IX2 semantics reproduced here: items *within* a group run concurrently, each
+ * honouring its own delay; groups run *sequentially*, the next starting once
+ * the current group's longest (delay + duration) has elapsed. The first group
+ * is applied instantly as the initial state rather than animated, because
+ * `useFirstGroupAsInitialState` is true.
+ *
+ * Note on target 355463fa-200a-e35f-3f49-bfcb2e8a5720: it is present in the
+ * IX2 data but NOT in this capture's markup (Coframe A/B-tests its own
+ * homepage, which is their product). Its action items therefore resolve to no
+ * element and are skipped — but their timings are still honoured, since IX2
+ * derives group duration from the action config, not from what resolved. That
+ * keeps the downstream groups' start times faithful.
+ *
+ * Note on 674d6aa7-...-b376 (`.hero__cta`): it is ALSO a `.fade-in` element
+ * carrying data-fade-delay="l", so upstream both this IX2 list and the site's
+ * own scroll fade-in script act on it. That overlap is reproduced rather than
+ * resolved — the original page has exactly the same two owners.
+ */
+import { prefersReducedMotion, type EffectInit, type Teardown } from './runtime';
+
+interface OpacityAction {
+  /** data-w-id of the IX2 target. */
+  targetId: string;
+  value: number;
+  delay: number;
+  duration: number;
+  easing: string;
+}
+
+/** Group 1 of action list "a-3" — applied instantly as the initial state. */
+const INITIAL_STATE: OpacityAction[] = [
+  { targetId: '674d6aa7-c193-2fe4-61dd-3519f496b376', value: 0, delay: 0, duration: 500, easing: '' },
+  { targetId: '674d6aa7-c193-2fe4-61dd-3519f496b395', value: 0, delay: 0, duration: 500, easing: '' },
+  { targetId: '355463fa-200a-e35f-3f49-bfcb2e8a5720', value: 0, delay: 0, duration: 0, easing: '' },
+];
+
+/** Groups 2..n of action list "a-3", in order. */
+const GROUPS: OpacityAction[][] = [
+  [
+    {
+      targetId: '355463fa-200a-e35f-3f49-bfcb2e8a5720',
+      value: 1,
+      delay: 500,
+      duration: 300,
+      easing: 'easeInOut',
+    },
+  ],
+  [
+    {
+      targetId: '674d6aa7-c193-2fe4-61dd-3519f496b376',
+      value: 1,
+      delay: 1300,
+      duration: 300,
+      easing: 'easeInOut',
+    },
+    {
+      targetId: '674d6aa7-c193-2fe4-61dd-3519f496b395',
+      value: 1,
+      delay: 1700,
+      duration: 300,
+      easing: 'easeInOut',
+    },
+  ],
+];
+
+/** Webflow easing names mapped to their CSS equivalents. */
+function cssEasing(easing: string): string {
+  switch (easing) {
+    case 'easeInOut':
+      return 'ease-in-out';
+    case 'easeIn':
+      return 'ease-in';
+    case 'easeOut':
+      return 'ease-out';
+    default:
+      return 'linear';
+  }
+}
+
+function find(root: ParentNode, targetId: string): HTMLElement | null {
+  return root.querySelector<HTMLElement>(`[data-w-id="${targetId}"]`);
+}
+
+/** Longest (delay + duration) in a group — how long IX2 waits before the next. */
+function groupDuration(group: OpacityAction[]): number {
+  return group.reduce((max, a) => Math.max(max, a.delay + a.duration), 0);
+}
+
+export const initCoframeHeroAnim: EffectInit = (
+  root: ParentNode = document,
+): Teardown | void => {
+  // No-op unless at least one of the action list's targets is on this page.
+  const anyTarget =
+    INITIAL_STATE.some((a) => find(root, a.targetId) !== null) ||
+    GROUPS.some((g) => g.some((a) => find(root, a.targetId) !== null));
+  if (!anyTarget) return;
+
+  const timers: number[] = [];
+  const animations: Animation[] = [];
+
+  // Final resting state of the whole list, used for the reduced-motion path.
+  const applyFinalState = () => {
+    for (const group of GROUPS) {
+      for (const action of group) {
+        const el = find(root, action.targetId);
+        if (el) el.style.opacity = String(action.value);
+      }
+    }
+  };
+
+  if (prefersReducedMotion()) {
+    // Show the hero immediately rather than animating it in. Skipping the
+    // animation without this would leave the initial state (opacity 0)
+    // permanently applied, hiding real content.
+    applyFinalState();
+    return;
+  }
+
+  // --- IX2 group 1: initial state, applied instantly ----------------------
+  for (const action of INITIAL_STATE) {
+    const el = find(root, action.targetId);
+    if (el) el.style.opacity = String(action.value);
+  }
+
+  // --- IX2 groups 2..n: sequential, items concurrent within a group -------
+  let groupStart = 0;
+  for (const group of GROUPS) {
+    for (const action of group) {
+      const at = groupStart + action.delay;
+      timers.push(
+        window.setTimeout(() => {
+          const el = find(root, action.targetId);
+          if (!el) return;
+          const to = String(action.value);
+
+          if (action.duration <= 0 || typeof el.animate !== 'function') {
+            el.style.opacity = to;
+            return;
+          }
+
+          const from = window.getComputedStyle(el).opacity;
+          const animation = el.animate(
+            [{ opacity: from }, { opacity: to }],
+            { duration: action.duration, easing: cssEasing(action.easing), fill: 'both' },
+          );
+          animations.push(animation);
+          // Commit the end state to an inline style so the element keeps it
+          // once the animation object is released.
+          animation.addEventListener('finish', () => {
+            el.style.opacity = to;
+          });
+        }, at),
+      );
+    }
+    groupStart += groupDuration(group);
+  }
+
+  return () => {
+    for (const t of timers) window.clearTimeout(t);
+    for (const a of animations) {
+      try {
+        a.cancel();
+      } catch {
+        /* teardown must never throw during unmount */
+      }
+    }
+  };
+};

--- a/coframecom-3/app/lib/coframeFadeIn.ts
+++ b/coframecom-3/app/lib/coframeFadeIn.ts
@@ -0,0 +1,89 @@
+/**
+ * Scroll fade-ins — a faithful port of the captured inline script
+ * `scrape/analysis/script-21.js`.
+ *
+ * Deliberately NOT the template's generic `createFadeIn`, which differs from
+ * this site in three ways that are all visible:
+ *   1. Selector. Upstream queries `.fade-in` and nothing else. The generic one
+ *      also matches `[data-fade]` / `[data-animate]`, which would animate
+ *      `div.compare-grid` — an element that carries a bare `data-fade` attribute
+ *      but no `.fade-in` class, and which the live site never animates (it
+ *      renders at full opacity). Matching the original selector exactly is what
+ *      keeps the replica faithful.
+ *   2. Threshold. Upstream defaults to 0.4 and reads a per-element override
+ *      from `data-fade-threshold`; the generic one uses 0.15 with a rootMargin.
+ *   3. Stagger. Upstream sets `style.animationDelay` from a `data-fade-delay`
+ *      keyword map; the generic one has an index-based stagger instead.
+ *
+ * The finished-state class is `faded-in`, confirmed present in the captured
+ * CSS (`.fade-in { ... } .faded-in { ... }`).
+ */
+import { prefersReducedMotion, type EffectInit, type Teardown } from './runtime';
+
+/** Upstream's `delayMapping`, verbatim. */
+const DELAY_MAPPING: Record<string, string> = {
+  s: '0.4s',
+  m: '0.8s',
+  l: '1.2s',
+  xl: '1.6s',
+};
+
+const SELECTOR = '.fade-in';
+const ACTIVE_CLASS = 'faded-in';
+const DEFAULT_THRESHOLD = 0.4;
+
+export const initCoframeFadeIn: EffectInit = (
+  root: ParentNode = document,
+): Teardown | void => {
+  const elements = Array.from(root.querySelectorAll<HTMLElement>(SELECTOR));
+  if (!elements.length) return;
+
+  if (prefersReducedMotion() || typeof IntersectionObserver === 'undefined') {
+    // Reveal everything at once: the class is what makes the content visible,
+    // so skipping it entirely would hide real copy.
+    for (const el of elements) el.classList.add(ACTIVE_CLASS);
+    return;
+  }
+
+  const observers: IntersectionObserver[] = [];
+
+  // Upstream declares ONE mutable `observer` variable and reassigns it inside
+  // the loop, so every callback closes over the shared binding and
+  // `observer.unobserve(...)` ends up addressing whichever observer was created
+  // last rather than the one that fired. The practical effect is that most
+  // elements are never unobserved and keep re-running the (idempotent) class
+  // add. That is upstream's real behaviour and is reproduced here rather than
+  // "fixed", since fixing it would change when the delay is re-applied.
+  let observer: IntersectionObserver | null = null;
+
+  const createObserver = (threshold = DEFAULT_THRESHOLD) =>
+    new IntersectionObserver(
+      (entries) => {
+        entries.forEach((entry) => {
+          if (!entry.isIntersecting) return;
+          const target = entry.target as HTMLElement;
+          const delayKey = target.getAttribute('data-fade-delay');
+          const delay = (delayKey ? DELAY_MAPPING[delayKey] : undefined) ?? '0s';
+          target.style.animationDelay = delay;
+          target.classList.add(ACTIVE_CLASS);
+          if (observer === null) return;
+          observer.unobserve(entry.target);
+        });
+      },
+      { threshold },
+    );
+
+  for (const element of elements) {
+    const attr = element.getAttribute('data-fade-threshold');
+    const parsed = attr === null ? Number.NaN : Number.parseFloat(attr);
+    const threshold = Number.isNaN(parsed) || parsed === 0 ? DEFAULT_THRESHOLD : parsed;
+    observer = createObserver(threshold);
+    observers.push(observer);
+    observer.observe(element);
+  }
+
+  return () => {
+    for (const o of observers) o.disconnect();
+    observer = null;
+  };
+};

--- a/coframecom-3/app/lib/coframeRive.ts
+++ b/coframecom-3/app/lib/coframeRive.ts
@@ -0,0 +1,263 @@
+/**
+ * Hero impact chart (Rive) plus its replay-button choreography.
+ *
+ * Three separately-verified constraints govern this module. Getting any one of
+ * them wrong produces a blank canvas or a wedged main thread with no error.
+ *
+ * 1. RENDERER BUILD. The live page loads `@rive-app/webgl2@2.35.0` (observed
+ *    fetching `unpkg.com/@rive-app/webgl2@2.35.0/rive.wasm` in this run's
+ *    network log, recorded in `scrape/runtime-requirements.json`). This `.riv`
+ *    does NOT render under the plain `@rive-app/canvas` build — no exception,
+ *    no console error, just an empty canvas. The wasm is self-hosted at
+ *    `/assets/rive/rive-webgl2.wasm` (verified byte-identical to the installed
+ *    package) so the page never reaches out to unpkg at runtime.
+ *
+ * 2. THE CONFIG ATTRIBUTES LIVE ON A WRAPPER DIV, not on the canvas. The
+ *    element is `div.impact__animation[data-rive-url]` with a bare `<canvas>`
+ *    child, so a `canvas[data-rive-url]` selector (the generic adapter's
+ *    default) matches nothing and the chart silently never mounts.
+ *
+ * 3. THE ANIMATION IS TRIGGER-DRIVEN, NOT AUTOPLAY. The state machine sits on
+ *    its idle entry state until a trigger input named `onRestart` fires;
+ *    `reset()` merely re-instantiates that same idle state, which renders a
+ *    static frame. Do not call `reset()`/`play()` before `onLoad` either: on a
+ *    not-yet-loaded instance that call never returns, because the task it
+ *    queues re-adds itself to the very queue it is draining, wedging the main
+ *    thread permanently.
+ *
+ * The replay choreography is Webflow IX2 action list "a-4" ("Play Chart
+ * Animation"), bound to MOUSE_CLICK on the replay button by event "e-5".
+ * Transcribed verbatim from the IX2 payload:
+ *
+ *   G1: GENERAL_DISPLAY  .impact__replay-button  "none"  delay     0
+ *       STYLE_OPACITY     .impact__replay-button  0       delay     0
+ *   G2: PLUGIN_RIVE       -> { name: "State Machine", inputs: { onRestart: true } }
+ *                                                   delay   100
+ *   G3: GENERAL_DISPLAY  .impact__replay-button  "flex"  delay 10000
+ *       STYLE_OPACITY     .impact__replay-button  1       delay 10000, duration 300
+ *
+ * The first play is not a separate code path: the captured inline script
+ * `scrape/analysis/script-29.js` does `replayButton.click()` on
+ * DOMContentLoaded, so initial play and user replay are the same sequence. That
+ * event has already fired by the time a React effect mounts, so the first play
+ * is triggered from Rive's own `onLoad` instead.
+ *
+ * Finally, note that codegen strips the replay button's captured inline
+ * `opacity:0; display:none` (both properties are in the sanitizer's strip
+ * list), and `.impact__replay-button` is `display:flex` in the stylesheet — so
+ * the button starts VISIBLE. Group 1 must therefore be applied at init, or it
+ * sits on top of the chart on first paint.
+ */
+import { type EffectInit, type Teardown } from './runtime';
+
+/* eslint-disable @typescript-eslint/no-explicit-any */
+type AnyModule = any;
+
+const HOST_SELECTOR = '[data-rive-url]';
+const REPLAY_SELECTOR = '.impact__replay-button';
+const WASM_URL = '/assets/rive/rive-webgl2.wasm';
+
+/** IX2 "a-4" constants. */
+export const RESTART_TRIGGER = 'onRestart';
+export const TRIGGER_DELAY_MS = 100;
+export const REVEAL_DELAY_MS = 10000;
+export const REVEAL_FADE_MS = 300;
+
+export interface CoframeRiveOptions {
+  /** Dynamic import of the renderer build the page used. */
+  load: () => Promise<AnyModule>;
+  wasmUrl?: string;
+}
+
+export function createCoframeRive(options: CoframeRiveOptions): EffectInit {
+  const { load, wasmUrl = WASM_URL } = options;
+
+  return function initCoframeRive(root: ParentNode = document): Teardown | void {
+    const host = root.querySelector<HTMLElement>(HOST_SELECTOR);
+    if (!host) return;
+
+    const canvas = host.querySelector('canvas');
+    if (!canvas) return;
+
+    const src = host.getAttribute('data-rive-url');
+    if (!src) return;
+
+    const stateMachine = host.getAttribute('data-rive-state-machine') ?? undefined;
+    const artboard = host.getAttribute('data-rive-artboard') ?? undefined;
+    const autoplay = host.getAttribute('data-rive-autoplay') !== 'false';
+    const replayButton = root.querySelector<HTMLElement>(REPLAY_SELECTOR);
+
+    let disposed = false;
+    let loaded = false;
+    let replayPending = false;
+    let rive: AnyModule = null;
+    const timers: number[] = [];
+
+    const clearTimers = () => {
+      for (const t of timers) window.clearTimeout(t);
+      timers.length = 0;
+    };
+
+    // --- IX2 a-4 group 1 -------------------------------------------------
+    const hideReplayButton = () => {
+      if (!replayButton) return;
+      replayButton.style.transition = '';
+      replayButton.style.display = 'none';
+      replayButton.style.opacity = '0';
+    };
+
+    // --- IX2 a-4 group 3 -------------------------------------------------
+    const revealReplayButton = () => {
+      if (!replayButton) return;
+      replayButton.style.display = 'flex';
+      replayButton.style.transition = `opacity ${REVEAL_FADE_MS}ms ease-in-out`;
+      // Next frame, so the transition has a start value to animate from.
+      requestAnimationFrame(() => {
+        if (!disposed && replayButton) replayButton.style.opacity = '1';
+      });
+    };
+
+    // Apply group 1 immediately: the sanitizer removed the inline styles that
+    // were keeping this button hidden at capture time.
+    hideReplayButton();
+
+    /** Fires the state-machine trigger. Safe only once `loaded` is true. */
+    const fireRestart = () => {
+      if (!rive || !stateMachine) return;
+      try {
+        const inputs = rive.stateMachineInputs?.(stateMachine);
+        if (!inputs) return;
+        const input = inputs.find((i: AnyModule) => i?.name === RESTART_TRIGGER);
+        if (!input) return;
+        // The IX2 payload expresses this as `inputs: { onRestart: true }`, which
+        // is ambiguous between a trigger and a boolean. This input is a trigger
+        // (type 58), but handle both shapes so a re-export as a boolean still
+        // works.
+        if (typeof input.fire === 'function') input.fire();
+        else input.value = true;
+      } catch (err) {
+        console.warn('[replica] Rive restart trigger failed:', err);
+      }
+    };
+
+    /** The full a-4 sequence. */
+    const runReplaySequence = () => {
+      if (disposed) return;
+      clearTimers();
+      hideReplayButton();
+      timers.push(window.setTimeout(fireRestart, TRIGGER_DELAY_MS));
+      timers.push(window.setTimeout(revealReplayButton, REVEAL_DELAY_MS));
+    };
+
+    const onReplayClick = (e: Event) => {
+      // The button is a div, not an anchor, so there is no navigation to
+      // suppress — but stop the click bubbling into any ancestor handler.
+      e.preventDefault();
+      if (!loaded) {
+        replayPending = true;
+        return;
+      }
+      runReplaySequence();
+    };
+
+    replayButton?.addEventListener('click', onReplayClick);
+
+    void load()
+      .then((mod: AnyModule) => {
+        if (disposed) return;
+
+        try {
+          mod.RuntimeLoader?.setWasmUrl?.(wasmUrl);
+        } catch {
+          /* older runtimes lack the setter */
+        }
+
+        const layout =
+          typeof mod.Layout === 'function'
+            ? new mod.Layout({
+                fit: mod.Fit?.[capitalise(host.getAttribute('data-rive-fit') ?? 'contain')] ?? mod.Fit?.Contain,
+                alignment:
+                  mod.Alignment?.[alignmentKey(host.getAttribute('data-rive-alignment'))] ??
+                  mod.Alignment?.Center,
+              })
+            : undefined;
+
+        try {
+          rive = new mod.Rive({
+            src,
+            canvas,
+            autoplay,
+            artboard,
+            stateMachines: stateMachine,
+            layout,
+            // Required by the webgl2 build so instances share one GL context.
+            useOffscreenRenderer: true,
+            onLoad: () => {
+              loaded = true;
+              if (disposed) return;
+              // Match the backing store to the CSS box, or the chart renders
+              // blurry / wrongly scaled.
+              try {
+                rive.resizeDrawingSurfaceToCanvas?.();
+              } catch {
+                /* best-effort */
+              }
+              // Stand in for script-29's DOMContentLoaded click, which has
+              // already fired by the time this effect mounts. Deferred a tick
+              // so no runtime call happens inside the onLoad callback itself.
+              const shouldPlay = replayPending || true;
+              replayPending = false;
+              if (shouldPlay) timers.push(window.setTimeout(runReplaySequence, 0));
+            },
+            onLoadError: (err: unknown) => {
+              console.warn('[replica] Rive failed to load the chart:', err);
+            },
+          });
+        } catch (err) {
+          console.warn('[replica] Rive failed to initialise:', err);
+        }
+      })
+      .catch((err: unknown) => {
+        console.warn(
+          '[replica] Rive runtime not installed — the chart canvas will stay blank. ' +
+            'Install the build reported in scrape/runtime-requirements.json.',
+          err,
+        );
+      });
+
+    const onResize = () => {
+      if (!loaded || !rive) return;
+      try {
+        rive.resizeDrawingSurfaceToCanvas?.();
+      } catch {
+        /* best-effort */
+      }
+    };
+    window.addEventListener('resize', onResize);
+
+    return () => {
+      disposed = true;
+      clearTimers();
+      window.removeEventListener('resize', onResize);
+      replayButton?.removeEventListener('click', onReplayClick);
+      try {
+        rive?.cleanup?.();
+      } catch {
+        /* teardown must never throw during unmount */
+      }
+    };
+  };
+}
+
+function capitalise(value: string): string {
+  return value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
+}
+
+/** Maps a Webflow alignment string such as "center" to Rive's enum key. */
+function alignmentKey(value: string | null): string {
+  if (!value) return 'Center';
+  return value
+    .split(/[\s-_]+/)
+    .map((part) => capitalise(part))
+    .join('');
+}

