cd coframecom-3 && node -e '
const fs=require("fs"),path=require("path");
const dir="app/generated";
let fadeIn=0, dataFade=0; const dataFadeEls=[];
for(const f of fs.readdirSync(dir).filter(f=>f.endsWith(".tsx"))){
  const s=fs.readFileSync(path.join(dir,f),"utf8");
  // count className occurrences containing fade-in as a whole class token
  const cls=s.match(/className="[^"]*"/g)||[];
  for(const c of cls){ if(/(^|[\s"])fade-in([\s"]|$)/.test(c)) fadeIn++; }
  const df=s.match(/data-fade(?![-a-z])/g)||[];
  dataFade+=df.length;
  if(df.length){
    const re=/<(\w+)[^>]*data-fade(?![-a-z])[^>]*>/g; let m;
    while((m=re.exec(s))){ const tag=m[0].slice(0,220); dataFadeEls.push(f+": "+tag.replace(/\s+/g," ")); }
  }
}
console.log("elements with .fade-in class :",fadeIn);
console.log("bare data-fade attributes    :",dataFade);
console.log("--- data-fade element(s) ---");
dataFadeEls.forEach(e=>console.log(e));
'

