const out = { hashAnchors: [], tabLinks: [], dropdownToggles: [], scrollY: window.scrollY, docHeight: document.documentElement.scrollHeight };
document.querySelectorAll('a[href^="#"]').forEach(a => {
  const href = a.getAttribute('href');
  out.hashAnchors.push({
    href,
    cls: a.className,
    targetExists: href.length > 1 ? !!document.querySelector(href) : false,
    role: a.getAttribute('role')
  });
});
document.querySelectorAll('.w-tab-link, [role="tab"]').forEach(el => {
  out.tabLinks.push({ tag: el.tagName, cls: el.className, href: el.getAttribute('href'), role: el.getAttribute('role') });
});
document.querySelectorAll('.w-dropdown-toggle, .w-dropdown').forEach(el => {
  out.dropdownToggles.push({ tag: el.tagName, cls: el.className, href: el.getAttribute('href') });
});
return JSON.stringify(out, null, 1);

