const swipers = Array.from(document.querySelectorAll('.swiper')).map(s => ({
  cls: s.className.split(' ').filter(c => c.startsWith('swiper') || c.includes('introduction') || c.includes('case')).join('.'),
  activeIndex: s.querySelector('.swiper-slide-active') ? Array.from(s.querySelectorAll('.swiper-slide')).indexOf(s.querySelector('.swiper-slide-active')) : -1,
}));
return JSON.stringify({
  scrollY: Math.round(window.scrollY),
  activeTab: document.querySelector('.introduction__step.w--current')?.textContent?.trim().slice(0, 40) ?? null,
  swipers,
}, null, 1);

const form = document.querySelector('.footer .newsletter-form__form') || document.querySelector('.newsletter-form__form');
const input = form.querySelector('.newsletter-form__text-field');
const btn = form.querySelector('.newsletter-form__button');
const done = form.parentElement.querySelector('.w-form-done');
form.scrollIntoView({ block: 'center' });
return JSON.stringify({
  inputRef: klenny.ref(input),
  btnRef: klenny.ref(btn),
  doneVisibleNow: done ? getComputedStyle(done).display : 'no-done-block',
  formDisplayNow: getComputedStyle(form).display,
});

const form = document.querySelector('.footer .newsletter-form__form') || document.querySelector('.newsletter-form__form');
const wrap = form.parentElement;
const done = wrap.querySelector('.w-form-done');
const fail = wrap.querySelector('.w-form-fail');
return JSON.stringify({
  url: location.href,
  hash: location.hash,
  scrollY: Math.round(window.scrollY),
  formDisplay: getComputedStyle(form).display,
  doneDisplay: done ? getComputedStyle(done).display : 'none-found',
  failDisplay: fail ? getComputedStyle(fail).display : 'none-found',
  doneText: done?.textContent?.trim().slice(0, 80) ?? null,
}, null, 1);

const form = document.querySelector('.footer .newsletter-form__form') || document.querySelector('.newsletter-form__form');
const rules = [];
for (const sheet of Array.from(document.styleSheets)) {
  let r; try { r = sheet.cssRules; } catch { continue; }
  for (const rule of Array.from(r)) {
    if (rule.style && rule.selectorText && /newsletter-form__form/.test(rule.selectorText) && rule.style.display) {
      rules.push({ sel: rule.selectorText, display: rule.style.display, important: rule.style.getPropertyPriority('display') });
    }
  }
}
return JSON.stringify({ inlineDisplay: form.style.display || '(none set)', computed: getComputedStyle(form).display, matchingRules: rules }, null, 1);
